    22	        container = NSPersistentContainer(name: containerName)
    23	        container.loadPersistentStores { _, error in
    24	            if let error = error {
    25	                print("Error loading core data: \(error)")
    26	            }
    27	        }
    28	    }
    29	    
    30	    private func save()   {
    31	        do {
    32	            try container.viewContext.save()
    33	        } catch let error {
    34	           print("Error saving to core data: \(error)")
    35	        }
    36	    }
    37	    
    38	    func addOrder(with data: [String: Any]) async throws {
    39	        do {
    40	            
    41	            //add order api
    42	            var request = GenericRequest()
    43	            request.method = .post
    44	            request.path = ApiConstants.ORDERS_URL
    45	            request.parameters = data
    46	            request.encoding = JSONEncoding.default
    47	            let _: EmptyData = try await ApiRequest.request(request)
    48	            
    49	            
    50	            //remove all data in CoreData
    51	            let fetchRequest:NSFetchRequest<NSFetchRequestResult> = NSFetchRequest(entityName: entityName)
    52	            let deleteRequest = NSBatchDeleteRequest(fetchRequest: fetchRequest)
    53	            try container.viewContext.execute(deleteRequest)
