    65	        } catch {
    66	            throw error
    67	        }
    68	    }
    69	    
    70	    func increaseFoodQuantity(foodId: Int64) throws {
    71	        do {
    72	            let savedFoods = try getFoods()
    73	            if let foodEntity = savedFoods.first(where: {$0.id == foodId}) {
    74	                // Update a current food entity
    75	                foodEntity.quantity += 1
    76	                save()
    77	            }
    78	        } catch let error {
    79	           throw error
    80	        }
    81	       
    82	    }
    83	    
    84	    func removeFoodFromCart(foodId: Int64) throws {
    85	        do {
    86	            let savedFoods = try getFoods()
    87	            if let food = savedFoods.first(where: {$0.id == foodId}) {
    88	                if food.quantity  == 1 {
    89	                    container.viewContext.delete(food)
    90	                } else {
    91	                    food.quantity -= 1
    92	                }
    93	                save()
    94	            }
    95	        } catch {
    96	            throw error
    97	        }
