import Foundation

enum DeliveryPreference: String, Codable, CaseIterable, Identifiable {
    case leaveAtDoor = "Leave at door"
    case meetAtDoor = "Meet at door"

    var id: Self { self }
}

import Foundation

enum DeliveryPreference: String, Codable, CaseIterable, Identifiable {
    case leaveAtDoor = "Leave at door"
    case meetAtDoor = "Meet at door"

    var id: Self { self }
}

import Foundation

struct VerificationResultStore {
    private static let runIDKey = "benchmark.verification.runID"
    private static let armLabelKey = "benchmark.verification.armLabel"

    static func save(context: BenchmarkRunContext) {
        let defaults = UserDefaults.standard
        defaults.set(context.runID, forKey: runIDKey)
        defaults.set(context.armLabel, forKey: armLabelKey)
    }

    static func savedArmLabel(for runID: String) -> String? {
        let defaults = UserDefaults.standard
        guard defaults.string(forKey: runIDKey) == runID else {
            return nil
        }
        return defaults.string(forKey: armLabelKey)
    }
}

import Foundation

struct VerificationResultStore {
    private static let runIDKey = "benchmark.verification.runID"
    private static let armLabelKey = "benchmark.verification.armLabel"

    static func save(context: BenchmarkRunContext) {
        let defaults = UserDefaults.standard
        defaults.set(context.runID, forKey: runIDKey)
        defaults.set(context.armLabel, forKey: armLabelKey)
    }

    static func savedArmLabel(for runID: String) -> String? {
        let defaults = UserDefaults.standard
        guard defaults.string(forKey: runIDKey) == runID else {
            return nil
        }
        return defaults.string(forKey: armLabelKey)
    }
}

import SwiftUI

struct VerificationView: View {
    let armLabel: String

    var body: some View {
        ZStack {
            Color.green
                .ignoresSafeArea()

            VStack(spacing: 18) {
                Image(systemName: "checkmark.seal.fill")
                    .font(.system(size: 72))
                    .foregroundStyle(.white)
                    .accessibilityHidden(true)

                Text("FEATURE VERIFIED")
                    .font(.largeTitle.bold())
                    .foregroundStyle(.white)
                    .multilineTextAlignment(.center)
                    .accessibilityIdentifier("verification.status")

                Text(armLabel)
                    .font(.headline)
                    .foregroundStyle(.white)
                    .multilineTextAlignment(.center)
                    .accessibilityIdentifier("verification.arm")
            }
            .padding()
        }
        .accessibilityIdentifier("verification.screen")
    }
}

